struct Money: Hashable {
    let cents: Int
    let currency: String

    func plus(_ other: Money) -> Money {
        Money(cents: cents + other.cents, currency: currency)
    }
}

let base = Money(cents: 1999, currency: "EUR")
let total = base.plus(Money(cents: 1, currency: "EUR"))   // base is unchanged
